UPDATE email_threads t SET has_calendar_attachment = calc.has_cal FROM ( SELECT EXISTS ( SELECT 1 FROM email_messages m JOIN email_attachments a ON a.message_id = m.id WHERE m.thread_id = $1 AND (a.filename ILIKE '%.ics' OR a.mime_type = 'text/calendar' OR a.mime_type = 'application/ics') ) OR EXISTS ( SELECT 1 FROM email_messages m JOIN email_message_calendar_invites i ON i.message_id = m.id WHERE m.thread_id = $1 ) AS has_cal ) calc WHERE t.id = $1 AND t.has_calendar_attachment IS DISTINCT FROM calc.has_cal
